<style>
.certificate-workspace{max-width:86rem;margin:0 auto}.certificate-workspace__header{margin-bottom:1rem}.certificate-base-workspace{box-sizing:border-box;width:100%;max-width:none}.certificate-editor{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(18rem,.65fr);gap:clamp(1.25rem,3vw,2.5rem);align-items:start}.certificate-section-heading{display:flex;gap:1rem;align-items:start;justify-content:space-between}.certificate-section-heading h2,.certificate-preview h3,.certificate-inventory h3{margin-top:0}.certificate-section-heading p{margin:.25rem 0;color:var(--chisimba-text-muted)}.certificate-workspace form{display:grid;gap:1rem}.certificate-workspace label{display:grid;gap:.35rem;font-weight:600}.certificate-workspace small{color:var(--chisimba-text-muted);font-weight:400}.certificate-workspace input[type=file]{box-sizing:border-box;width:100%;padding:.7rem}.certificate-colours{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.certificate-colour-control{display:grid;grid-template-columns:4.5rem 1fr;gap:.65rem;align-items:center}.certificate-colour-control input[type=color]{width:4.5rem;height:3rem;padding:.2rem;border:1px solid var(--chisimba-border);border-radius:.4rem;background:var(--chisimba-surface)}.certificate-colour-control output{font:inherit;font-weight:500}.certificate-preview{position:sticky;top:1rem}.certificate-preview__page{aspect-ratio:1/1.414;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.65rem;padding:1.5rem;text-align:center;color:#1f2937;background:#fdfcf8;border:5px double #b49352;box-shadow:var(--chisimba-shadow)}.certificate-preview__page strong{font-family:serif;font-size:clamp(1.3rem,2.4vw,2rem)}.certificate-preview__page small{color:#b49352;font-weight:700}.certificate-preview__page b{font-family:serif;font-size:1.1rem}.certificate-preview__page i{width:45%;margin-top:1rem;border-top:1px solid #1f2937}.certificate-preview__seal{display:grid;place-items:center;width:3.5rem;height:3.5rem;color:#fff;background:#b49352;border-radius:50%;font-size:1.4rem}.certificate-inventory{margin-top:1.5rem;padding-top:1.25rem;border-top:1px solid var(--chisimba-border)}.certificate-records{display:grid;gap:.55rem}.certificate-record{display:flex;gap:1rem;align-items:center;justify-content:space-between;padding:.75rem;border:1px solid var(--chisimba-border);border-radius:.55rem;background:var(--chisimba-surface-subtle)}.certificate-record p{margin:.15rem 0;color:var(--chisimba-text-muted)}.certificate-record__colours{display:inline-flex;gap:.3rem;margin-left:.5rem}.certificate-record__swatch{display:inline-block;width:1rem;height:1rem;border:1px solid var(--chisimba-border-strong);border-radius:50%}.certificate-record__actions{display:flex;flex-wrap:wrap;gap:.45rem;justify-content:flex-end}.certificate-record__actions .button,.certificate-record__actions button{gap:.35rem;white-space:nowrap}.certificate-empty{color:var(--chisimba-text-muted)}.certificate-lower-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem;margin-top:1.5rem;align-items:start}.certificate-course{box-sizing:border-box;max-width:none}.certificate-saving{color:var(--chisimba-text-muted)}@media(max-width:60rem){.certificate-editor,.certificate-lower-grid{grid-template-columns:1fr}.certificate-preview{position:static;max-width:28rem}}@media(max-width:40rem){.certificate-colours{grid-template-columns:1fr}.certificate-section-heading,.certificate-record{align-items:stretch;flex-direction:column}.certificate-record__actions{justify-content:flex-start}}
</style>
<script>
(function(){'use strict';
var state={bases:<?php echo json_encode(array_values($certificateBases),$jsonFlags); ?>,signers:<?php echo json_encode(array_values($certificateSigners),$jsonFlags); ?>,assignment:<?php echo json_encode($certificateAssignment?:false,$jsonFlags); ?>};
var actionIcons=<?php echo json_encode($actionIcons,$jsonFlags); ?>,actionUrls=<?php echo json_encode($actionUrls,$jsonFlags); ?>,actionLabels={edit:<?php echo json_encode($text('edit','Edit'),$jsonFlags); ?>,remove:<?php echo json_encode($text('delete','Delete'),$jsonFlags); ?>,preview:<?php echo json_encode($text('previewdownload','View/download sample'),$jsonFlags); ?>,confirm:<?php echo json_encode($text('confirmdelete','Delete this saved item?'),$jsonFlags); ?>,inuse:<?php echo json_encode($text('inuse','This item is assigned to a course and cannot be deleted.'),$jsonFlags); ?>};
var status=document.getElementById('certificate-status'),baseForm=document.querySelector('[data-kind="base"]'),signerForm=document.querySelector('[data-kind="signer"]'),assignmentForm=document.querySelector('[data-kind="assignment"]');
function notice(message,error){status.innerHTML='';var p=document.createElement('p');p.className='chisimba-notice '+(error?'chisimba-notice--error':'chisimba-notice--success chisimba-notice--transient');p.setAttribute('role',error?'alert':'status');p.textContent=message;status.appendChild(p);}
function fill(form,record,names){names.forEach(function(name){if(form.elements[name])form.elements[name].value=record[name]||'';});form.elements.id.value=record.id;form.scrollIntoView({behavior:'smooth',block:'start'});}
function actionButton(label,icon,className){var button=document.createElement('button'),span=document.createElement('span');button.type='button';button.className='button '+className;button.innerHTML=icon;span.textContent=label;button.appendChild(span);return button;}
function deleteRecord(kind,id){if(!window.confirm(actionLabels.confirm))return;var form=kind==='base'?baseForm:signerForm,data=new FormData();data.append('ajax','1');data.append('id',id);data.append('csrf_token',form.querySelector('input[name="csrf_token"]').value);fetch(actionUrls[kind==='base'?'deletebase':'deletesigner'],{method:'POST',body:data,credentials:'same-origin'}).then(function(response){return response.json();}).then(function(result){document.querySelectorAll('input[name="csrf_token"]').forEach(function(input){input.value=result.csrfToken;});if(!result.ok){notice(result.message==='inuse'?actionLabels.inuse:'<?php echo $esc($text('invalid','Check the details and try again.')); ?>',true);return;}state.bases=result.bases||[];state.signers=result.signers||[];state.assignment=result.assignment||false;render();notice('<?php echo $esc($text('deleted','Deleted.')); ?>',false);}).catch(function(){notice('<?php echo $esc($text('savefailed','The changes could not be saved. Please try again.')); ?>',true);});}
function recordList(target,records,kind){target.innerHTML='';if(!records.length){var empty=document.createElement('p');empty.className='certificate-empty';empty.textContent=kind==='base'?'No certificate designs have been saved yet.':'No signers have been saved yet.';target.appendChild(empty);return;}var list=document.createElement('div');list.className='certificate-records';records.forEach(function(record){var row=document.createElement('div');row.className='certificate-record';var copy=document.createElement('div'),strong=document.createElement('strong'),detail=document.createElement('p');strong.textContent=record.name;detail.textContent=kind==='base'?(record.organisation+' · '+record.company_name):(record.title||'Signer');copy.append(strong,detail);if(kind==='base'){var colours=document.createElement('span');colours.className='certificate-record__colours';[record.primary_colour,record.accent_colour].forEach(function(colour){var swatch=document.createElement('i');swatch.className='certificate-record__swatch';swatch.style.backgroundColor=colour;swatch.title=colour;colours.appendChild(swatch);});strong.appendChild(colours);}var actions=document.createElement('div');actions.className='certificate-record__actions chisimba-row-actions';var edit=actionButton(actionLabels.edit,actionIcons.edit,'chisimba-button-secondary');edit.addEventListener('click',function(){if(kind==='base')fill(baseForm,record,['name','organisation','company_name','company_location','website_url','primary_colour','accent_colour']);else fill(signerForm,record,['name','title']);syncPreview();});actions.appendChild(edit);if(kind==='base'){var preview=document.createElement('a'),previewLabel=document.createElement('span');preview.className='button chisimba-button-secondary';preview.target='_blank';preview.rel='noopener';preview.href=actionUrls.previewbase.replace('__ID__',record.id);preview.innerHTML=actionIcons.preview;previewLabel.textContent=actionLabels.preview;preview.appendChild(previewLabel);actions.appendChild(preview);}var remove=actionButton(actionLabels.remove,actionIcons.delete,'chisimba-button-danger');remove.addEventListener('click',function(){deleteRecord(kind,record.id);});actions.appendChild(remove);row.append(copy,actions);list.appendChild(row);});target.appendChild(list);}
function options(select,records,current){if(!select)return;select.innerHTML='';var blank=document.createElement('option');blank.value='';blank.textContent='Choose…';select.appendChild(blank);records.forEach(function(record){var option=document.createElement('option');option.value=record.id;option.textContent=record.name;option.selected=record.id===current;select.appendChild(option);});}
function render(){var baseList=document.getElementById('certificate-base-list'),signerList=document.getElementById('certificate-signer-list');if(baseList)recordList(baseList,state.bases,'base');if(signerList)recordList(signerList,state.signers,'signer');if(assignmentForm){options(assignmentForm.elements.base_id,state.bases,state.assignment&&state.assignment.base_id);options(assignmentForm.elements.signer_id,state.signers,state.assignment&&state.assignment.signer_id);}}
function syncPreview(){if(!baseForm)return;var primary=baseForm.elements.primary_colour.value,accent=baseForm.elements.accent_colour.value,page=document.querySelector('.certificate-preview__page');baseForm.elements.primary_colour.nextElementSibling.textContent=primary;baseForm.elements.accent_colour.nextElementSibling.textContent=accent;page.style.color=primary;page.style.borderColor=accent;page.querySelector('small').style.color=accent;page.querySelector('.certificate-preview__seal').style.backgroundColor=accent;page.querySelector('i').style.borderColor=primary;}
document.querySelectorAll('input[type="color"]').forEach(function(input){input.addEventListener('input',syncPreview);});
document.querySelectorAll('.certificate-ajax-form').forEach(function(form){form.addEventListener('submit',function(event){event.preventDefault();var saving=form.querySelector('.certificate-saving'),button=form.querySelector('button[type="submit"]'),data=new FormData(form);data.append('ajax','1');saving.hidden=false;button.disabled=true;fetch(form.action,{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'}).then(function(response){if(!response.ok)throw new Error('save');return response.json();}).then(function(result){document.querySelectorAll('input[name="csrf_token"]').forEach(function(input){input.value=result.csrfToken;});if(!result.ok){notice('<?php echo $esc($text('invalid','Check the details and try again.')); ?>',true);return;}state.bases=result.bases||[];state.signers=result.signers||[];state.assignment=result.assignment||false;render();notice(result.message==='assigned'?'<?php echo $esc($text('assigned','The course certificate was saved.')); ?>':'<?php echo $esc($text('saved','Saved.')); ?>',false);}).catch(function(){notice('<?php echo $esc($text('savefailed','The changes could not be saved. Please try again.')); ?>',true);}).finally(function(){saving.hidden=true;button.disabled=false;});});});
var newBase=document.querySelector('.certificate-new-base'),newSigner=document.querySelector('.certificate-new-signer'),resetColours=document.querySelector('.certificate-reset-colours');if(newBase)newBase.addEventListener('click',function(){baseForm.reset();baseForm.elements.id.value='';syncPreview();});if(newSigner)newSigner.addEventListener('click',function(){signerForm.reset();signerForm.elements.id.value='';});if(resetColours)resetColours.addEventListener('click',function(){baseForm.elements.primary_colour.value='#1f2937';baseForm.elements.accent_colour.value='#b49352';syncPreview();});render();syncPreview();
}());
</script>
